import { readFileSync, writeFileSync } from "node:fs";
import { Resvg } from "@resvg/resvg-js";

const ROOT = "/home/agus/workspace/asermax/nagara";
const corpus = `${ROOT}/.scratch/cloudflare-migration/spikes/image-processing/corpus`;
const env = (f) => Object.fromEntries(readFileSync(f, "utf8").split("\n").filter((l) => l.includes("=")).map((l) => [l.slice(0, l.indexOf("=")), l.slice(l.indexOf("=") + 1)]));
const GEMINI = env(`${ROOT}/api/.env`).NAGARA_GEMINI_API_KEY;
const AIG = env(`${ROOT}/pipeline/.dev.vars`).CLOUDFLARE_API_KEY;
const ACCOUNT = "2b32439a1d8fdcdf00a9f7f654a11a6d";
const BASE = `https://gateway.ai.cloudflare.com/v1/${ACCOUNT}/nagara/google-ai-studio/v1beta/models`;
const MODEL = process.env.MODEL ?? "gemini-3.5-flash-lite";

const py = readFileSync(`${ROOT}/api/app/service/describe.py`, "utf8");
const tpl = py.match(/_IMAGE_PROMPT_TEMPLATE = """\\\n([\s\S]*?)"""/)[1].replace(/\\\n/g, "");
const prompt = tpl.replace("{title}", "(untitled)").replace("{alt}", "(none)");

const files = (process.env.FILES ?? "badge,github-badge,codecov,logo-python,formula1,formula3,osi,normal").split(",");
const variants = (process.env.VARIANTS ?? "a,b,c,d").split(",");
const b64 = (b) => Buffer.from(b).toString("base64");

const call = async (parts, model = MODEL) => {
  const body = { contents: [{ role: "user", parts }], generationConfig: { responseMimeType: "application/json", responseSchema: { type: "object", properties: { spoken: { type: "string" } }, required: ["spoken"] } } };
  const t = performance.now();
  const res = await fetch(`${BASE}/${model}:generateContent`, { method: "POST", headers: { "content-type": "application/json", "x-goog-api-key": GEMINI, "cf-aig-authorization": `Bearer ${AIG}` }, body: JSON.stringify(body) });
  const ms = Math.round(performance.now() - t);
  const text = await res.text();
  let j; try { j = JSON.parse(text); } catch {}
  if (res.status !== 200) return { status: res.status, ms, error: text.slice(0, 600) };
  const out = j.candidates?.[0]?.content?.parts?.map((p) => p.text).join("") ?? "";
  let spoken = out; try { spoken = JSON.parse(out).spoken; } catch {}
  const u = j.usageMetadata ?? {};
  return { status: 200, ms, spoken, prompt_tokens: u.promptTokenCount, out_tokens: u.candidatesTokenCount, thoughts: u.thoughtsTokenCount, total: u.totalTokenCount, details: u.promptTokensDetails, cache: res.headers.get("cf-aig-cache-status"), finish: j.candidates?.[0]?.finishReason };
};

const results = [];
for (const f of files) {
  const svg = readFileSync(`${corpus}/${f}.svg`, "utf8");
  const png = new Resvg(svg, { fitTo: { mode: "width", value: 768 }, font: { loadSystemFonts: true, defaultFontFamily: "Liberation Sans" } }).render().asPng();
  writeFileSync(`results/${f}.png`, png);
  for (const v of variants) {
    const parts = {
      a: [{ text: prompt }, { inlineData: { mimeType: "image/png", data: b64(png) } }],
      b: [{ text: prompt }, { inlineData: { mimeType: "text/plain", data: b64(svg) } }],
      c: [{ text: `${prompt}\n\nSVG markup:\n${svg}` }],
      d: [{ text: prompt }, { inlineData: { mimeType: "image/svg+xml", data: b64(svg) } }],
    }[v];
    const r = await call(parts);
    results.push({ file: f, variant: v, svgBytes: svg.length, pngBytes: png.length, ...r });
    console.log(f, v, r.status, r.ms + "ms", r.prompt_tokens ?? "", r.spoken ?? r.error);
  }
}
writeFileSync(`results/${process.env.OUT ?? "run1"}.json`, JSON.stringify(results, null, 2));
E
node src/run.mjs 2>&1 | tee results/run1.log

