cd /home/agus/workspace/asermax/nagara/.scratch/cloudflare-migration/spikes/svg-describe; cat > src/report.mjs <<'E'
import { readFileSync, writeFileSync } from "node:fs";
const r = JSON.parse(readFileSync("results/run1.json", "utf8"));
const names = { a: "(a) PNG 768 px", b: "(b) text/plain part", c: "(c) markup in prompt", d: "(d) image/svg+xml part" };
let o = "";
for (const f of [...new Set(r.map((x) => x.file))]) {
  const x = r.filter((y) => y.file === f);
  o += `\n### ${f}.svg (${x[0].svgBytes} B markup, ${x[0].pngBytes} B PNG)\n\n| Variant | Description | Prompt tok | Out tok | ms |\n|---|---|---|---|---|\n`;
  for (const y of x) o += `| ${names[y.variant]} | ${y.spoken} | ${y.prompt_tokens ?? `~${y.total - y.out_tokens} (derived)`} | ${y.out_tokens} | ${y.ms} |\n`;
}
const avg = (v, k) => Math.round(r.filter((y) => y.variant === v).reduce((s, y) => s + (y[k] ?? 0), 0) / 8);
o += "\n### Averages over the 8 SVGs\n\n| Variant | ms | out tok |\n|---|---|---|\n" + ["a", "b", "c", "d"].map((v) => `| ${names[v]} | ${avg(v, "ms")} | ${avg(v, "out_tokens")} |`).join("\n") + "\n";
writeFileSync("results/tables.md", o);
E
